export function audioPath(pack,id,lang,gender){
  const catalog=pack==='core'?CORE_CATALOG:COURSE_CATALOG;
  const root=pack==='core'?CORE_ROOT:COURSE_ROOT;
  const category=catalog[id];
  return category?`${root}/${lang}/${gender}/${category}/${id}.mp3`:null;
}

export function packFor(id){
  if(COURSE_CATALOG[id]) return 'course';
  if(CORE_CATALOG[id]) return 'core';
  return null;
}
